[CmdletBinding()]
param(
    [string]$RepositoryUrl = "https://github.com/pingdotgg/t3code.git",
    [string]$ExpectedCommit = "c1ec1915fc16f3dc1ec5d47d9a97f6210a574526",
    [string]$BundlePath = ""
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest
$Root = Split-Path -Parent $PSScriptRoot
$Staging = Join-Path $Root "source\staging\t3code-clone"
$BundleDir = Join-Path $Root "input\upstream_reference\git-bundles"
$BundleOut = Join-Path $BundleDir "t3code-$ExpectedCommit.bundle"

function Invoke-Native([scriptblock]$Command, [string]$Description) {
    & $Command
    if ($LASTEXITCODE -ne 0) {
        throw "$Description failed with exit code $LASTEXITCODE"
    }
}

if (-not (Get-Command git -ErrorAction SilentlyContinue)) {
    throw "Git is required for source acquisition."
}
if (-not (Get-Command python -ErrorAction SilentlyContinue)) {
    throw "Python is required for transactional source intake."
}

Remove-Item -Recurse -Force $Staging -ErrorAction SilentlyContinue
New-Item -ItemType Directory -Force (Split-Path $Staging -Parent) | Out-Null
New-Item -ItemType Directory -Force $BundleDir | Out-Null

$effectiveBundle = $BundlePath
if (-not $effectiveBundle -and (Test-Path $BundleOut)) {
    $effectiveBundle = $BundleOut
}

if ($effectiveBundle) {
    $effectiveBundle = (Resolve-Path $effectiveBundle).Path
    if (-not (Test-Path $effectiveBundle)) { throw "Bundle not found: $effectiveBundle" }
    Invoke-Native { git bundle verify $effectiveBundle } "Git bundle verification"
    Invoke-Native { git clone $effectiveBundle $Staging } "Git bundle clone"
    Invoke-Native { git -C $Staging remote set-url origin $RepositoryUrl } "Remote URL assignment"
} else {
    Invoke-Native { git clone --no-local $RepositoryUrl $Staging } "Full repository clone"
}

Invoke-Native { git -C $Staging cat-file -e "$ExpectedCommit^{commit}" } "Pinned commit lookup"
Invoke-Native { git -C $Staging checkout --detach $ExpectedCommit } "Pinned commit checkout"
Invoke-Native { git -C $Staging fsck --full --strict } "Git integrity verification"

$actual = (& git -C $Staging rev-parse HEAD).Trim().ToLowerInvariant()
if ($actual -ne $ExpectedCommit.ToLowerInvariant()) {
    throw "Pinned commit mismatch: expected $ExpectedCommit, got $actual"
}

$dirty = (& git -C $Staging status --porcelain) -join "`n"
if ($LASTEXITCODE -ne 0) { throw "Unable to inspect source status." }
if ($dirty) { throw "Source checkout is dirty before intake.`n$dirty" }

Invoke-Native { git -C $Staging bundle create $BundleOut --all } "Reusable Git bundle creation"
Invoke-Native { git bundle verify $BundleOut } "Reusable Git bundle verification"

python (Join-Path $PSScriptRoot "ingest_source.py") --directory $Staging
if ($LASTEXITCODE -ne 0) { throw "Transactional source intake failed." }

$primary = Join-Path $Root "source\primary"
Invoke-Native { git -C $primary fsck --full --strict } "Ingested Git integrity verification"
$final = (& git -C $primary rev-parse HEAD).Trim().ToLowerInvariant()
if ($final -ne $ExpectedCommit.ToLowerInvariant()) { throw "Ingested source commit mismatch." }
if ((& git -C $primary status --porcelain) -join "`n") { throw "Ingested source is dirty." }

Write-Host "Source acquired at $ExpectedCommit"
Write-Host "Reusable bundle: $BundleOut"
